// ============================================================
// ETAPA 1 — LIMPIEZA DE DATOS
// ============================================================
// Responsabilidades:
//   a) Descartar mensajes de sistema (agricultura/sistema/*)
//   b) Validar estructura mínima del payload
//   c) Descartar valores NaN, null o infinitos
//   d) Validar rangos físicos de cada variable (descarta lecturas
//      claramente erróneas como T° = -50°C o RH = 200%)
//   e) Deduplicar usando una ventana corta por (sensor_id, valor)
//      para amortiguar reintentos del simulador.
// ============================================================

if (msg.topic && msg.topic.startsWith('agricultura/sistema/')) {
    return null;
}
const p = msg.payload;
if (typeof p !== 'object' || p === null) {
    node.warn('Payload no es objeto JSON');
    return null;
}
if (!p.variable || p.valor === undefined || p.valor === null) {
    node.warn('Mensaje sin variable o valor: ' + msg.topic);
    return null;
}

// Convertir a número y validar finitud
const v = parseFloat(p.valor);
if (!Number.isFinite(v)) {
    node.warn('Valor no finito: ' + p.valor + ' en ' + msg.topic);
    return null;
}

// Rangos físicos por variable (descartar errores groseros)
// NO son rangos agronómicos — esos van en la Fase 5 (alertas)
const RANGOS_FISICOS = {
    temperatura_aire:   [-20, 55],     // °C
    temperatura_suelo:  [-20, 60],
    humedad_relativa:   [0, 100],      // %
    humedad_suelo:      [0, 100],
    precipitacion:      [0, 500],      // mm/día (record mundial diario ~1825 mm, dejamos margen alto)
    radiacion_solar:    [0, 40],       // MJ/m²/día
    velocidad_viento:   [0, 50],       // m/s
    ph_suelo:           [0, 14]
};
const rango = RANGOS_FISICOS[p.variable];
if (rango && (v < rango[0] || v > rango[1])) {
    node.warn(`Valor fuera de rango físico (${p.variable}=${v}): ${msg.topic}`);
    return null;
}

// Deduplicación leve por (sensor_id, valor) en ventana de 1 segundo
// (los reintentos de QoS=1 pueden generar duplicados ocasionales)
const keyDedup = (p.sensor_id || '') + ':' + v.toFixed(3);
const now = Date.now();
const dedup = context.get('dedup') || {};
if (dedup[keyDedup] && now - dedup[keyDedup] < 1000) {
    return null;   // duplicado dentro de ventana, descartar silenciosamente
}
dedup[keyDedup] = now;
// Limpieza periódica del cache de dedup (cada 100 mensajes)
const counter = (context.get('counter') || 0) + 1;
context.set('counter', counter);
if (counter % 100 === 0) {
    const cutoff = now - 10000;   // 10s
    Object.keys(dedup).forEach(k => { if (dedup[k] < cutoff) delete dedup[k]; });
}
context.set('dedup', dedup);

// Pasa al siguiente nodo con valor normalizado
p.valor = v;
msg.payload = p;
return msg;

// ============================================================
// ETAPA 2 — TRANSFORMACIÓN
// ============================================================
// Responsabilidades:
//   a) Normalizar unidades (km/h → m/s si llegara, °F → °C)
//   b) Convertir radiación de MJ/m²/día a W/m² instantáneo cuando aplique
//   c) Enriquecer con metadatos de la parcela (departamento, altitud)
//   d) Estandarizar timestamps a UTC ISO-8601
// ============================================================

const p = msg.payload;

// Metadata estática por parcela (consistente con Fase 1 — altitudes IGAC)
const META_PARCELA = {
    parcela_1: { departamento: 'Valle del Cauca', altitud_m: 1001 },
    parcela_2: { departamento: 'Valle del Cauca', altitud_m: 980 },
    parcela_3: { departamento: 'Tolima',          altitud_m: 323 },
    parcela_4: { departamento: 'Casanare',        altitud_m: 350 }
};
const meta = META_PARCELA[p.parcela] || { departamento: 'desconocido', altitud_m: 0 };
p.departamento = meta.departamento;
p.altitud_m    = meta.altitud_m;

// Normalización defensiva de unidades — si el simulador alguna vez
// publica viento en km/h, convertir a m/s
if (p.variable === 'velocidad_viento' && p.unidad === 'km/h') {
    p.valor = p.valor / 3.6;
    p.unidad = 'm/s';
}
if ((p.variable === 'temperatura_aire' || p.variable === 'temperatura_suelo') && p.unidad === '°F') {
    p.valor = (p.valor - 32) * 5/9;
    p.unidad = '°C';
}

// Timestamp normalizado (ISO UTC)
let ts;
if (p.timestamp_real) {
    const t = Date.parse(p.timestamp_real);
    ts = isNaN(t) ? Date.now() : t;
} else {
    ts = Date.now();
}
p.timestamp_iso = new Date(ts).toISOString();
msg.timestamp = ts;
msg.payload = p;
return msg;

// Preparar punto InfluxDB para el bucket agro_iot_data (mediciones limpias)
// (formato compatible con node-red-contrib-influxdb v2)
const p = msg.payload;
const fields = {};
fields[p.variable] = parseFloat(p.valor);
const tags = {
    parcela:      p.parcela,
    cultivo:      p.cultivo,
    ubicacion:    p.ubicacion,
    departamento: p.departamento,
    variable:     p.variable,
    unidad:       p.unidad || '',
    sensor_id:    p.sensor_id || ''
};
return {
    payload:   [fields, tags],
    timestamp: msg.timestamp
};

// ============================================================
// ETAPA 3 — CÁLCULO DE INDICADORES AGROCLIMÁTICOS
// ============================================================
// Mantiene un cache por parcela con la ÚLTIMA lectura de cada variable.
// Cuando llegan dos variables relacionadas (T° + RH), se calculan:
//
//   - Índice de calor (Heat Index)            — sensación térmica
//   - Punto de rocío (Dew Point)               — riesgo de condensación
//   - Déficit de presión de vapor (VPD)        — estrés hídrico foliar
//
// Los indicadores se publican como msg.payload.indicadores[] y
// fluyen al nodo de persistencia hacia agro_iot_indicadores.
// ============================================================

const p = msg.payload;
const parcela = p.parcela;
if (!parcela) return msg;

// Cache global por parcela: { temperatura_aire: {v, t}, humedad_relativa: {v, t}, ... }
const cache = flow.get('cache_parcelas') || {};
cache[parcela] = cache[parcela] || {};
cache[parcela][p.variable] = { v: parseFloat(p.valor), t: msg.timestamp };
flow.set('cache_parcelas', cache);

const ind = [];
const pc = cache[parcela];

// --- Helpers ---
const hasFresh = (key, maxAgeMs = 10 * 60 * 1000) => {
    return pc[key] && (msg.timestamp - pc[key].t) <= maxAgeMs;
};

// --- 3.1 Índice de calor (NWS Steadman/Rothfusz) ---
// Requiere T° y HR frescas. Válido cuando T > 26.7 °C.
if (hasFresh('temperatura_aire') && hasFresh('humedad_relativa')) {
    const T = pc.temperatura_aire.v;   // °C
    const RH = pc.humedad_relativa.v;  // %
    const Tf = T * 9/5 + 32;            // a °F
    let HIf;
    if (Tf < 80) {
        HIf = 0.5 * (Tf + 61.0 + (Tf - 68.0) * 1.2 + RH * 0.094);
    } else {
        HIf = -42.379 + 2.04901523*Tf + 10.14333127*RH
            - 0.22475541*Tf*RH - 0.00683783*Tf*Tf
            - 0.05481717*RH*RH + 0.00122874*Tf*Tf*RH
            + 0.00085282*Tf*RH*RH - 0.00000199*Tf*Tf*RH*RH;
    }
    const HI = (HIf - 32) * 5/9;        // a °C
    ind.push({ nombre: 'indice_calor', valor: +HI.toFixed(2), unidad: '°C' });

    // --- 3.2 Punto de rocío (Magnus-Tetens) ---
    const a = 17.625, b = 243.04;
    const alpha = Math.log(Math.max(RH, 0.01) / 100) + a * T / (b + T);
    const Td = (b * alpha) / (a - alpha);
    ind.push({ nombre: 'punto_rocio', valor: +Td.toFixed(2), unidad: '°C' });

    // --- 3.3 Déficit de presión de vapor (VPD, Allen et al. FAO-56) ---
    // es(T) = 0.6108 * exp(17.27*T/(T+237.3))   [kPa]
    // ea    = es(T) * RH / 100
    // VPD   = es - ea
    const es = 0.6108 * Math.exp(17.27 * T / (T + 237.3));
    const ea = es * RH / 100;
    const VPD = es - ea;
    ind.push({ nombre: 'vpd', valor: +VPD.toFixed(3), unidad: 'kPa' });
}

// --- 3.4 Grados-día de crecimiento (GDD) ---
// Necesita T_max y T_min frescas; T_base por cultivo:
//   caña = 18°C (Cenicaña), arroz = 10°C (FEDEARROZ)
if (hasFresh('temperatura_aire')) {
    // En ausencia de T_max/T_min explícitos del simulador,
    // se usa la T° media instantánea como proxy. (En la práctica
    // este indicador se acumula diariamente vía task Flux — ver Fase 5).
    const T = pc.temperatura_aire.v;
    const T_base = (p.cultivo === 'caña') ? 18.0 : 10.0;
    const gdd_instantaneo = Math.max(0, T - T_base);
    ind.push({
        nombre: 'gdd_instantaneo',
        valor: +gdd_instantaneo.toFixed(2),
        unidad: '°C·día',
        meta: { t_base: T_base }
    });
}

// Si no se calculó ningún indicador todavía, no propagar
if (ind.length === 0) return null;

msg.payload.indicadores = ind;
return msg;

// ============================================================
// ETAPA 4 — VARIABLES DERIVADAS
// ============================================================
// Evapotranspiración de referencia (ETo) por el método Hargreaves
// (FAO-56, ec. 52), versión simplificada que sólo requiere:
//   T_max, T_min, T_media, Ra (radiación extraterrestre)
//
// Aproximación válida cuando no se dispone de viento y humedad fiables.
// Útil para programar riego en caña y arroz.
// ============================================================

const p = msg.payload;
const parcela = p.parcela;
const cache = flow.get('cache_parcelas') || {};
const pc = cache[parcela] || {};

// Ra (radiación extraterrestre) — aproximada con un valor mensual constante
// para la latitud ecuatorial colombiana (~4°N). Valores en MJ/m²/día.
// Fuente: tabla 2.6 FAO-56 (Allen et al. 1998), latitud 5°N promedio anual.
const Ra_aprox = 36.0;   // MJ/m²/día (aprox. ecuatorial, valor medio anual)

const Tmean = pc.temperatura_aire ? pc.temperatura_aire.v : null;
// El simulador publica T_aire como serie temporal; usamos rango aproximado
// de amplitud diaria típica (Fase 1: 8-12 °C). En la práctica, los valores
// reales de T_max y T_min llegarán como variables explícitas en versiones
// futuras del simulador. Aquí estimamos.
if (Tmean !== null) {
    const Tmax_est = Tmean + 5.0;
    const Tmin_est = Tmean - 5.0;
    // Hargreaves: ETo = 0.0023 * (Tmean+17.8) * sqrt(Tmax-Tmin) * Ra
    const Tdiff = Math.max(Tmax_est - Tmin_est, 0.1);
    const ETo = 0.0023 * (Tmean + 17.8) * Math.sqrt(Tdiff) * Ra_aprox * 0.408;
    // Multiplicar por 0.408 convierte MJ/m²/día a mm/día (factor de conversión
    // energía → agua usado en FAO-56 ec. 20)
    msg.payload.indicadores = msg.payload.indicadores || [];
    msg.payload.indicadores.push({
        nombre: 'eto_hargreaves',
        valor: +ETo.toFixed(3),
        unidad: 'mm/día',
        meta: { metodo: 'Hargreaves FAO-56', Ra_MJm2dia: Ra_aprox }
    });
}

return msg;

// Convertir cada indicador calculado en un punto independiente
// para el bucket agro_iot_indicadores.
const p = msg.payload;
if (!p.indicadores || p.indicadores.length === 0) return null;

const mensajes = p.indicadores.map(ind => {
    const fields = {};
    fields[ind.nombre] = parseFloat(ind.valor);
    const tags = {
        parcela:      p.parcela,
        cultivo:      p.cultivo,
        ubicacion:    p.ubicacion,
        departamento: p.departamento || 'desconocido',
        indicador:    ind.nombre,
        unidad:       ind.unidad || ''
    };
    return {
        payload:   [fields, tags],
        timestamp: msg.timestamp
    };
});
// El nodo InfluxDB Out acepta arrays de mensajes — los splittea
return [mensajes];
